# Notebook cell 325: # @title  Wilson Success-Probability Interval
def phase4_wilson_interval(
    successes,
    trials,
    z=1.959963984540054
):
    """
    Two-sided Wilson score interval for a Bernoulli proportion.
    """

    successes = int(
        successes
    )

    trials = int(
        trials
    )


    if trials <= 0:

        return (
            float("nan"),
            float("nan")
        )


    p_hat = (

        successes
        /
        trials
    )


    z2 = (
        z
        *
        z
    )


    denominator = (

        1.0

        +

        z2
        /
        trials
    )


    center = (

        p_hat

        +

        z2
        /
        (
            2.0
            *
            trials
        )
    ) / denominator


    half_width = (

        z

        *

        math.sqrt(

            (
                p_hat
                *
                (
                    1.0
                    -
                    p_hat
                )
                /
                trials
            )

            +

            (
                z2
                /
                (
                    4.0
                    *
                    trials
                    *
                    trials
                )
            )
        )

        /

        denominator
    )


    return (

        max(
            0.0,
            center - half_width
        ),

        min(
            1.0,
            center + half_width
        )
    )

lo, hi = (
    phase4_wilson_interval(
        8,
        8
    )
)


# Notebook cell 326: # @title  Configuration Summary Builder
def phase4_summarize_calibration_config(
    group
):

    group = group.copy()


    successes = (

        group[
            group[
                "delivery_success_canonical"
            ]
        ]

        .copy()
    )


    total_trials = int(
        len(
            group
        )
    )


    successful_trials = int(
        len(
            successes
        )
    )


    failed_trials = (

        total_trials
        -
        successful_trials
    )


    service_success_probability = (

        successful_trials

        /

        total_trials
    )


    (
        success_ci_low,
        success_ci_high
    ) = phase4_wilson_interval(

        successful_trials,

        total_trials
    )


    # ============================================================
    # Helper for success-conditioned statistics
    # ============================================================

    def success_stat(
        column,
        statistic
    ):

        if successful_trials == 0:

            return float(
                "nan"
            )


        series = pd.to_numeric(

            successes[
                column
            ],

            errors="coerce"
        )


        if statistic == "mean":

            return float(
                series.mean()
            )


        if statistic == "std":

            return float(
                series.std(
                    ddof=1
                )
            )


        if statistic == "median":

            return float(
                series.median()
            )


        if statistic == "min":

            return float(
                series.min()
            )


        if statistic == "max":

            return float(
                series.max()
            )


        if statistic == "q25":

            return float(
                series.quantile(
                    0.25
                )
            )


        if statistic == "q75":

            return float(
                series.quantile(
                    0.75
                )
            )


        raise ValueError(
            f"Unsupported statistic: {statistic}"
        )


    first = (
        group.iloc[0]
    )


    # ============================================================
    # Proxy bias relative to actual successful delivery.
    # ============================================================

    proxy_delivery_s = float(
        first[
            "delivery_proxy_s"
        ]
    )


    mean_actual_delivery_s = (
        success_stat(
            "actual_delivery_s",
            "mean"
        )
    )


    median_actual_delivery_s = (
        success_stat(
            "actual_delivery_s",
            "median"
        )
    )


    if (
        successful_trials > 0
        and proxy_delivery_s > 0.0
    ):

        mean_actual_to_proxy_ratio = (

            mean_actual_delivery_s

            /

            proxy_delivery_s
        )


        median_actual_to_proxy_ratio = (

            median_actual_delivery_s

            /

            proxy_delivery_s
        )


    else:

        mean_actual_to_proxy_ratio = (
            float("nan")
        )

        median_actual_to_proxy_ratio = (
            float("nan")
        )


    # ============================================================
    # Delivered visibility loss relative to fresh prediction
    # ============================================================

    mean_actual_visibility = (
        success_stat(
            "actual_visibility",
            "mean"
        )
    )


    if successful_trials > 0:

        mean_visibility_delta = (

            mean_actual_visibility

            -

            float(
                first[
                    "predicted_visibility"
                ]
            )
        )

    else:

        mean_visibility_delta = (
            float("nan")
        )


    return pd.Series(
        {

            # ----------------------------------------------------
            # Configuration identity
            # ----------------------------------------------------

            "config_index":
                int(
                    first[
                        "config_index"
                    ]
                ),

            "total_distance_km":
                float(
                    first[
                        "total_distance_km"
                    ]
                ),

            "repeater_count":
                int(
                    first[
                        "repeater_count"
                    ]
                ),

            "hop_count":
                int(
                    first[
                        "hop_count"
                    ]
                ),

            "mode_count":
                int(
                    first[
                        "mode_count"
                    ]
                ),

            "elementary_distance_km":
                float(
                    first[
                        "elementary_distance_km"
                    ]
                ),


            # ----------------------------------------------------
            # Pre-execution router prediction
            # ----------------------------------------------------

            "single_mode_success_probability":
                float(
                    first[
                        "single_mode_success_probability"
                    ]
                ),

            "multiplexed_cycle_success_probability":
                float(
                    first[
                        "multiplexed_cycle_success_probability"
                    ]
                ),

            "predicted_visibility":
                float(
                    first[
                        "predicted_visibility"
                    ]
                ),

            "predicted_fidelity":
                float(
                    first[
                        "predicted_fidelity"
                    ]
                ),

            "predicted_qber":
                float(
                    first[
                        "predicted_qber"
                    ]
                ),

            "generation_proxy_s":
                float(
                    first[
                        "generation_proxy_s"
                    ]
                ),

            "delivery_proxy_s":
                proxy_delivery_s,

            "memory_coherence_cost":
                float(
                    first[
                        "memory_coherence_cost"
                    ]
                ),


            # ----------------------------------------------------
            # Finite service-budget outcome
            # ----------------------------------------------------

            "total_trials":
                total_trials,

            "successful_trials":
                successful_trials,

            "failed_trials":
                failed_trials,

            "service_success_probability":
                float(
                    service_success_probability
                ),

            "service_success_ci95_low":
                float(
                    success_ci_low
                ),

            "service_success_ci95_high":
                float(
                    success_ci_high
                ),


            # ----------------------------------------------------
            # Delivery time | success
            # ----------------------------------------------------

            "mean_actual_delivery_s":
                mean_actual_delivery_s,

            "std_actual_delivery_s":
                success_stat(
                    "actual_delivery_s",
                    "std"
                ),

            "median_actual_delivery_s":
                median_actual_delivery_s,

            "q25_actual_delivery_s":
                success_stat(
                    "actual_delivery_s",
                    "q25"
                ),

            "q75_actual_delivery_s":
                success_stat(
                    "actual_delivery_s",
                    "q75"
                ),

            "min_actual_delivery_s":
                success_stat(
                    "actual_delivery_s",
                    "min"
                ),

            "max_actual_delivery_s":
                success_stat(
                    "actual_delivery_s",
                    "max"
                ),


            # ----------------------------------------------------
            # Pair-rate statistics
            # ----------------------------------------------------

            "mean_successful_pair_rate_per_s":
                success_stat(
                    "actual_pair_rate_per_s",
                    "mean"
                ),

            # Failed trials are explicitly zero here.
            "mean_effective_pair_rate_per_s":
                float(
                    group[
                        "effective_pair_rate_per_s"
                    ]
                    .mean()
                ),


            # ----------------------------------------------------
            # Delivered quality | success
            # ----------------------------------------------------

            "mean_actual_visibility":
                mean_actual_visibility,

            "std_actual_visibility":
                success_stat(
                    "actual_visibility",
                    "std"
                ),

            "mean_actual_fidelity":
                success_stat(
                    "actual_fidelity",
                    "mean"
                ),

            "mean_actual_qber":
                success_stat(
                    "actual_predicted_qber",
                    "mean"
                ),


            # ----------------------------------------------------
            # Work | success
            # ----------------------------------------------------

            "mean_generation_cycles":
                success_stat(
                    "elementary_generation_cycles",
                    "mean"
                ),

            "mean_optical_attempts":
                success_stat(
                    "optical_mode_attempts",
                    "mean"
                ),

            "mean_bsm_attempts":
                success_stat(
                    "bsm_attempts",
                    "mean"
                ),


            # ----------------------------------------------------
            # Proxy-calibration diagnostics
            # ----------------------------------------------------

            "mean_actual_to_proxy_ratio":
                float(
                    mean_actual_to_proxy_ratio
                ),

            "median_actual_to_proxy_ratio":
                float(
                    median_actual_to_proxy_ratio
                ),

            "mean_visibility_delta":
                float(
                    mean_visibility_delta
                )
        }
    )


