# Notebook cell 346: # @title  Cross-Validated Regression Evaluator
def phase4_cross_validate_regression(
    dataframe,
    feature_columns,
    target_column,
    models,
    splits=5,
    random_seed=4_200_001
):

    X = (

        dataframe[
            feature_columns
        ]

        .to_numpy(
            dtype=float
        )
    )


    y = (

        dataframe[
            target_column
        ]

        .to_numpy(
            dtype=float
        )
    )


    cv = KFold(

        n_splits=(
            splits
        ),

        shuffle=True,

        random_state=(
            random_seed
        )
    )


    model_rows = []

    prediction_frames = []


    for model_name, model_template in models.items():

        oof_pred = np.full(

            len(
                dataframe
            ),

            np.nan,

            dtype=float
        )


        fold_rows = []


        for fold_index, (
            train_index,
            test_index
        ) in enumerate(
            cv.split(
                X
            ),
            start=1
        ):

            model = clone(
                model_template
            )


            model.fit(

                X[
                    train_index
                ],

                y[
                    train_index
                ]
            )


            fold_pred = model.predict(

                X[
                    test_index
                ]
            )


            oof_pred[
                test_index
            ] = fold_pred


            fold_rows.append(
                {

                    "model":
                        model_name,

                    "fold":
                        fold_index,

                    "mae":
                        mean_absolute_error(
                            y[
                                test_index
                            ],
                            fold_pred
                        ),

                    "rmse":
                        math.sqrt(
                            mean_squared_error(
                                y[
                                    test_index
                                ],
                                fold_pred
                            )
                        ),

                    "r2":
                        r2_score(
                            y[
                                test_index
                            ],
                            fold_pred
                        )
                }
            )


        assert (
            np.isfinite(
                oof_pred
            )
            .all()
        )


        overall_mae = (
            mean_absolute_error(
                y,
                oof_pred
            )
        )


        overall_rmse = math.sqrt(

            mean_squared_error(
                y,
                oof_pred
            )
        )


        overall_r2 = (
            r2_score(
                y,
                oof_pred
            )
        )


        model_rows.append(
            {

                "model":
                    model_name,

                "oof_mae":
                    overall_mae,

                "oof_rmse":
                    overall_rmse,

                "oof_r2":
                    overall_r2,

                "fold_mae_mean":
                    float(
                        np.mean(
                            [
                                row[
                                    "mae"
                                ]
                                for row
                                in fold_rows
                            ]
                        )
                    ),

                "fold_mae_std":
                    float(
                        np.std(
                            [
                                row[
                                    "mae"
                                ]
                                for row
                                in fold_rows
                            ],
                            ddof=1
                        )
                    ),

                "fold_rmse_mean":
                    float(
                        np.mean(
                            [
                                row[
                                    "rmse"
                                ]
                                for row
                                in fold_rows
                            ]
                        )
                    ),

                "fold_rmse_std":
                    float(
                        np.std(
                            [
                                row[
                                    "rmse"
                                ]
                                for row
                                in fold_rows
                            ],
                            ddof=1
                        )
                    )
            }
        )


        pred_frame = dataframe[
            [
                "config_index",
                *feature_columns
            ]
        ].copy()


        pred_frame[
            "model"
        ] = model_name


        pred_frame[
            "actual_target"
        ] = y


        pred_frame[
            "oof_prediction"
        ] = oof_pred


        prediction_frames.append(
            pred_frame
        )


    results_df = (

        pd.DataFrame(
            model_rows
        )

        .sort_values(
            "oof_rmse"
        )

        .reset_index(
            drop=True
        )
    )


    predictions_df = (

        pd.concat(
            prediction_frames,
            ignore_index=True
        )
    )


    return (
        results_df,
        predictions_df
    )


