# Notebook cell 360: # @title Reliability Calibration Setup
import math

import numpy as np

import pandas as pd

from sklearn.base import clone

from sklearn.pipeline import Pipeline

from sklearn.preprocessing import (
    StandardScaler
)

from sklearn.linear_model import (
    LogisticRegression
)

from sklearn.model_selection import (
    GroupKFold
)

from sklearn.metrics import (
    roc_auc_score,
    brier_score_loss,
    log_loss
)

PHASE4E4_RELIABILITY_FEATURES = [

    "elementary_distance_km",
    "repeater_count",
    "multiplexed_cycle_success_probability"
]

PHASE4E4_OUTER_SPLITS = 5

PHASE4E4_INNER_SPLITS = 4

PHASE4E4_BASE_RELIABILITY_MODEL = Pipeline(
    [
        (
            "scale",
            StandardScaler()
        ),

        (
            "logistic",
            LogisticRegression(

                C=1.0,

                class_weight="balanced",

                max_iter=10_000,

                solver="lbfgs"
            )
        )
    ]
)

for feature in PHASE4E4_RELIABILITY_FEATURES:

    print(
        "  -",
        feature
    )


# Notebook cell 361: # @title  Reliability Calibration Dataset
required_columns = {

    "config_index",

    "elementary_distance_km",
    "repeater_count",
    "multiplexed_cycle_success_probability",

    "delivery_success_canonical"
}

missing = (

    required_columns
    -
    set(
        phase4_raw.columns
    )
)

if missing:

    raise RuntimeError(

        "Missing required reliability columns: "

        +

        ", ".join(
            sorted(
                missing
            )
        )
    )

PHASE4E4_RELIABILITY_DF = (

    phase4_raw[
        [
            "config_index",

            *PHASE4E4_RELIABILITY_FEATURES,

            "delivery_success_canonical"
        ]
    ]

    .copy()

    .reset_index(
        drop=True
    )
)

PHASE4E4_RELIABILITY_DF[
    "target_success"
] = (

    PHASE4E4_RELIABILITY_DF[
        "delivery_success_canonical"
    ]

    .astype(
        int
    )
)


# Notebook cell 362: # @title  Platt Probability Calibrator
def phase4e4_fit_platt_calibrator(
    decision_scores,
    targets
):

    decision_scores = np.asarray(
        decision_scores,
        dtype=float
    ).reshape(
        -1,
        1
    )


    targets = np.asarray(
        targets,
        dtype=int
    )


    if (
        len(
            np.unique(
                targets
            )
        )
        !=
        2
    ):

        raise RuntimeError(
            "Platt calibration requires both success and failure samples."
        )


    # Very weak regularization:
    # effectively ordinary sigmoid calibration.
    calibrator = LogisticRegression(

        C=1_000_000.0,

        class_weight=None,

        max_iter=10_000,

        solver="lbfgs"
    )


    calibrator.fit(

        decision_scores,

        targets
    )


    return calibrator


# Notebook cell 372: # @title  Fit Final Calibrated Reliability Model
X_full = (

    PHASE4E4_RELIABILITY_DF[
        PHASE4E4_RELIABILITY_FEATURES
    ]

    .to_numpy(
        dtype=float
    )
)

y_full = (

    PHASE4E4_RELIABILITY_DF[
        "target_success"
    ]

    .to_numpy(
        dtype=int
    )
)

groups_full = (

    PHASE4E4_RELIABILITY_DF[
        "config_index"
    ]

    .to_numpy()
)

full_oof_scores = np.full(

    len(
        PHASE4E4_RELIABILITY_DF
    ),

    np.nan,

    dtype=float
)

full_calibration_cv = GroupKFold(

    n_splits=5
)

for (
    train_index,
    valid_index
) in full_calibration_cv.split(

    X_full,

    y_full,

    groups_full
):

    model = clone(
        PHASE4E4_BASE_RELIABILITY_MODEL
    )


    model.fit(

        X_full[
            train_index
        ],

        y_full[
            train_index
        ]
    )


    full_oof_scores[
        valid_index
    ] = (

        model
        .decision_function(

            X_full[
                valid_index
            ]
        )
    )

PHASE4_FINAL_RELIABILITY_CALIBRATOR = (

    phase4e4_fit_platt_calibrator(

        full_oof_scores,

        y_full
    )
)

PHASE4_FINAL_RELIABILITY_MODEL = clone(

    PHASE4E4_BASE_RELIABILITY_MODEL
)

PHASE4_FINAL_RELIABILITY_MODEL.fit(

    X_full,

    y_full
)
